const TIME_LIMIT: int = 7804;
const OPENING_BUFFER: int = 120;
const TH14_KUNAI: int = 496;
const TH14_GLOW_BALL: int = 880;

// Source VELTIME 1799/1834: same heading, one scalar ramp, no later
// logical-speed consumer or concurrent angular effect. ANIM is omitted;
// its initial -4*velocity remains in sh_dist below.
xformdef SPEED_RAMP(target: fx) { step_speed(target, 120); }

// Source at4 EX slots (1879-1887) are preserved here as configuration evidence:
// 5 SETSPRITE(32,1); 6 STEP(30,1,0,0,0,0); 7 WAIT(60);
// 8 ACCEL(2,.02,999); 9 GOTO(8);
// 14 SETSPRITE(32,3); 15 STEP(30,1,1,0,0,0); 16 WAIT(60);
// 17 VELTIME(120,2,999).
// Slots 1-4 are empty and no REACT=1 is installed anywhere in this closure.
// funcSet5 therefore never transfers the PC to 5/14. Do not execute these
// unreachable records or borrow the preceding card's REACT initialization.

// BossCard6_at: seven fixed fans. Source direction decreases six times
// per full seven-colour wave (the seventh subtraction is immediately undone).
async sub boss_fans() {
    var a: angle = -90deg;
    var n: int = 12;
    if global(GVAR_RANK) == 0 { n = 8; }
    if global(GVAR_RANK) == 1 { n = 11; }
    sh_reset(0);
    sh_count(0, n, 1);
    sh_speed(0, 1fx, 0fx);
    sh_dist(0, 28fx); // etDist32 - ANIM4*1
    for wave in 0..20000 {
        if $frame - self_int(1) >= 7200 { break; }
        for k in 0..7 {
            var color: int = 2;
            if k == 1 { color = 14; }
            if k == 2 { color = 13; }
            if k == 3 { color = 10; }
            if k == 4 { color = 8; }
            if k == 5 { color = 6; }
            if k == 6 { color = 4; }
            sh_sprite(0, TH14_KUNAI, color);
            sh_angle(0, a, 585 as angle); // source B=.0561 rad
            sh_fire(0);
            if k < 6 { a = a - (9362 as angle); } // .897598 rad
        }
        wait(self_int(2)); // live source I2, not a spawn-time snapshot
    }
}

// Snapshot the source F2/F3/I0/I3 separately for each enmCreate. The
// EffChargePoint2 F2/F3/I0 uses are visual only; I3 sets actual bullet colour.
async sub small_caster(kind: int, color: int, f2: angle, f3: angle, i0: int, deadline: int) {
    set_invuln(65535);
    set_hitbox(12fx);
    set_hurtbox(12fx);
    set_enemy_flag(ENEMY_NO_BODY, 1); // source flagSet(3), persists
    // Source 1677/1696/1714 waits belong to the child, not to its creator.
    wait(102);
    sh_reset(0);
    sh_sprite(0, TH14_GLOW_BALL, color); // source type32 -> target type33 TH14_GLOW_BALL
    sh_ring(0, 1);
    sh_count(0, 7, 1);
    sh_speed(0, 1fx, 0fx);
    sh_dist(0, 28fx);
    if kind == 0 { sh_xform(0, SPEED_RAMP(2.5fx)); }
    if kind == 1 { sh_xform(0, SPEED_RAMP(3.5fx)); }
    var period: int = 70;
    if kind == 0 {
        if global(GVAR_RANK) == 0 { period = 180; }
        if global(GVAR_RANK) == 1 { period = 90; }
        if global(GVAR_RANK) == 2 { period = 80; }
    }
    if kind == 1 {
        period = 50;
        if global(GVAR_RANK) == 0 { period = 100; }
    }
    if kind < 2 {
        for wave in 0..20000 {
            if $frame >= deadline { break; }
            var a: angle = aim_player();
            if kind == 0 {
                // Original RANDF2 sampled once per etOn, +/-20 degrees.
                var u: fx = (rand(65536)-32768) as fx / 32768;
                a = a + ((3641fx*u) as int as angle);
            }
            sh_angle(0, a, 520 as angle); // mode3 M=1 ignores layer step
            sh_fire(0);
            wait(period);
        }
    } else {
        // Source at4 is a rotating seven-way ring; callback remains inert.
        var ring_a: angle = -45deg;
        var count: int = 5;
        period = 70;
        var speed: fx = 2.2fx;
        if global(GVAR_RANK) == 0 { count = 1; period = 160; speed = 1.5fx; }
        if global(GVAR_RANK) == 1 { count = 3; period = 120; speed = 1.5fx; }
        if global(GVAR_RANK) == 2 { count = 4; period = 100; speed = 1.8fx; }
        sh_speed(0, speed, 0fx);
        sh_dist(0, 32fx-4fx*speed);
        for group in 0..20000 {
            if $frame >= deadline { break; }
            for shot in 0..count {
                if $frame >= deadline { break; }
                sh_angle(0, ring_a, 520 as angle);
                sh_fire(0);
                ring_a = ring_a - (910 as angle); // .087266 rad
                wait(20);
            }
            wait(period);
        }
    }
    // Source idle is cut by BossDead's enmKillAll, not natural attack return.
    while $frame < deadline { wait(1); }
}

sub create_pair(kind: int, dx: fx, dy: fx, color: int, deadline: int) {
    _ = spawn_enemy($self_x-dx, $self_y+dy, 70000, 0, 0, 0,
        small_caster(kind, color, 45deg, 20deg, 7, deadline));
    _ = spawn_enemy($self_x+dx, $self_y+dy, 70000, 0, 0, 0,
        small_caster(kind, color, 135deg, -20deg, 6, deadline));
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Boss6 686/688/710/714: restore player, HP8000, move, wait180.
    set_player_hitbox(2.5fx);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(180);
    // BossCard6 timerReset1581 is independent of the wrapper's timerReset.
    set_self_int(1, $frame);
    var deadline: int = $frame+7200;
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    // moveLimit(0,128,280,256): stationary centre never touches a limit.
    wait(60);
    wait(60);
    // BossCup3 has only visual/ext-damage state and an unconditional idle.
    set_self_int(2, 100);
    spawn boss_fans();
    // funcSet5 installed with F0=64/F1=128. No marked bullet exists;
    // callback has no reachable effect in this isolated source closure.
    wait(60);
    create_pair(0, 64fx, 32fx, 5, deadline);
    while $self_hp > 6500 && $frame-self_int(1) <= 5400 { wait(1); }
    if $frame-self_int(1) <= 5400 { wait(60); }
    create_pair(1, 128fx, 48fx, 6, deadline);
    while $self_hp > 3300 && $frame-self_int(1) <= 5400 { wait(1); }
    if $frame-self_int(1) <= 5400 { wait(60); }
    create_pair(2, 160fx, 64fx, 3, deadline);
    while $frame < deadline {
        if $frame-self_int(1) >= 5400 { set_self_int(2, 50); }
        wait(1);
    }
    // BossDead boundary only: stop source fire and children immediately,
    // clear remaining bullets after source +60; do not enter next content.
    kill_all_enemies(KILL_SILENT);
    wait(60);
    clear_bullets();
}

async sub control() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(24fx);
    // This is the real stationary Boss, with the source 48x48 round body.
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 128fx, 8000, 0, 0, 0, control);
    loop { wait(600); }
}
